css:
/* From Uiverse.io by krlozCJ - Tags: input, search */
.__UIV_SCOPE__ .container {
  position: relative;
  --size-button: 40px;
  color: white;
}

.__UIV_SCOPE__ .input {
  padding-left: var(--size-button);
  height: var(--size-button);
  font-size: 15px;
  border: none;
  color: #fff;
  outline: none;
  width: var(--size-button);
  transition: all ease 0.3s;
  background-color: #191A1E;
  box-shadow: 1.5px 1.5px 3px #0e0e0e, -1.5px -1.5px 3px rgb(95 94 94 / 25%), inset 0px 0px 0px #0e0e0e, inset 0px -0px 0px #5f5e5e;
  border-radius: 50px;
  cursor: pointer;
}

.__UIV_SCOPE__ .input:focus,
.__UIV_SCOPE__ .input:not(:invalid) {
  width: 200px;
  cursor: text;
  box-shadow: 0px 0px 0px #0e0e0e, 0px 0px 0px rgb(95 94 94 / 25%), inset 1.5px 1.5px 3px #0e0e0e, inset -1.5px -1.5px 3px #5f5e5e;
}

.__UIV_SCOPE__ .input:focus + .icon,
.__UIV_SCOPE__ .input:not(:invalid) + .icon {
  pointer-events: all;
  cursor: pointer;
}

.__UIV_SCOPE__ .container .icon {
  position: absolute;
  width: var(--size-button);
  height: var(--size-button);
  top: 0;
  left: 0;
  padding: 8px;
  pointer-events: none;
}

.__UIV_SCOPE__ .container .icon svg {
  width: 100%;
  height: 100%;
}
